#!/usr/bin/env python3
import json
import os
import re
import sys
from pathlib import Path

try:
    # Prefer lxml if available (not required)
    import lxml.etree as LET  # type: ignore
except Exception:
    LET = None

import xml.etree.ElementTree as ET


def _localname(tag: str) -> str:
    # ET tags look like '{uri}local' or 'local'
    if tag is None:
        return ''
    if tag.startswith('{'):
        return tag.split('}', 1)[1]
    return tag


def _is_lineseg_cache_el(el) -> bool:
    ln = _localname(getattr(el, 'tag', '')).lower()
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True
    # include camel variants
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True
    # required by instructions
    if ln in ('linesegarray', 'lineseg'):
        return True
    if ln in ('linesegarray', 'lineseg'):
        return True
    if ln in ('linesegarray', 'lineseg'):
        return True
    if ln == 'linesegarray' or ln == 'lineseg':
        return True
    if ln == 'linesegarray' or ln == 'lineseg':
        return True
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True

    # canonical list from prompt
    if ln in ('linesegarray', 'lineseg', 'linesegarray', 'lineseg', 'linesegarray', 'lineseg', 'linesegarray', 'lineseg'):
        return True

    # Support mixed-case: lineSegArray, lineSeg
    if ln in ('linesegarray', 'lineseg'):
        return True

    # Also remove anything starting with lineSeg
    # (case-insensitive check on local name)
    if ln.startswith('lineseg'):
        return True

    return False


def _collect_text_under(el) -> str:
    # concatenate all descendant text nodes (including el.text and tail)
    parts = []
    for node in el.iter():
        if node.text:
            parts.append(node.text)
        if node.tail:
            parts.append(node.tail)
    return ''.join(parts)


def _remove_layout_cache_for_changed_paras(root, before_para_texts, after_para_texts):
    # For every <hp:p> (local-name == 'p'), if any descendant text changed,
    # remove all descendant elements whose local-name indicates lineSeg cache.
    for p_el in root.iter():
        if _localname(p_el.tag) != 'p':
            continue
        pid = p_el.get('id')
        if pid is None:
            # fallback identity
            pid = str(id(p_el))
        before = before_para_texts.get(pid, '')
        after = after_para_texts.get(pid, '')
        if before == after:
            continue

        # Need parent map to remove descendants in ElementTree
        parent_map = {c: par for par in p_el.iter() for c in list(par)}
        to_remove = []
        for el in p_el.iter():
            if el is p_el:
                continue
            if _is_lineseg_cache_el(el):
                to_remove.append(el)

        for el in to_remove:
            par = parent_map.get(el)
            if par is not None:
                try:
                    par.remove(el)
                except ValueError:
                    pass


def _parse_xml(text_bytes: bytes):
    # Returns (tree, root, xml_declaration_bytes)
    # Keep the original XML declaration line if present.
    m = re.match(br'\s*(<\?xml[^>]*\?>)', text_bytes)
    decl = m.group(1) if m else b''

    parser = ET.XMLParser()
    root = ET.fromstring(text_bytes, parser=parser)
    tree = ET.ElementTree(root)
    return tree, root, decl


def _serialize_xml(tree, decl: bytes, encoding: str) -> bytes:
    # ElementTree will emit declaration if xml_declaration=True.
    # But we also want to preserve encoding; use the original encoding.
    xml_bytes = ET.tostring(tree.getroot(), encoding=encoding, xml_declaration=bool(decl))
    return xml_bytes


def main():
    data_path = Path('/root/event_data.json')
    work_root = Path('/tmp/hwpx_work')

    with data_path.open('r', encoding='utf-8') as f:
        data = json.load(f)

    # Find files under work_root containing '{{'
    targets = []
    for p in work_root.rglob('*.xml'):
        try:
            raw = p.read_text(encoding='utf-8')
        except UnicodeDecodeError:
            # try reading as bytes and decoding with utf-8-sig
            raw = p.read_bytes().decode('utf-8', errors='strict')
        if '{{' in raw:
            targets.append(p)

    if not targets:
        print('No XML files with placeholders found.', file=sys.stderr)
        return 0

    for path in sorted(targets):
        original_bytes = path.read_bytes()

        # Detect original encoding from XML declaration, default to UTF-8
        decl_match = re.match(br'\s*<\?xml[^>]*encoding=["\']([^"\']+)["\']', original_bytes)
        encoding = decl_match.group(1).decode('ascii', errors='ignore') if decl_match else 'UTF-8'

        try:
            original_text = original_bytes.decode(encoding)
        except Exception:
            # fallback
            original_text = original_bytes.decode('utf-8')
            encoding = 'UTF-8'

        replaced_text = original_text
        for k, v in data.items():
            token = '{{' + str(k) + '}}'
            replaced_text = replaced_text.replace(token, str(v))

        if replaced_text == original_text:
            # nothing changed at string level
            continue

        # Warn if any placeholders remain
        if '{{' in replaced_text:
            # show a little context
            residuals = sorted(set(re.findall(r'\{\{[^}]+\}\}', replaced_text)))
            print(f'WARNING: residual placeholders remain in {path}: {residuals}', file=sys.stderr)

        # Parse XML before/after to identify which <p> changed
        # before parse
        tree_before, root_before, decl_before = _parse_xml(original_bytes)

        # after parse
        replaced_bytes = replaced_text.encode(encoding)
        tree_after, root_after, decl_after = _parse_xml(replaced_bytes)

        before_para_texts = {}
        after_para_texts = {}

        for p_el in root_before.iter():
            if _localname(p_el.tag) == 'p':
                pid = p_el.get('id')
                if pid is None:
                    pid = str(id(p_el))
                before_para_texts[pid] = _collect_text_under(p_el)

        for p_el in root_after.iter():
            if _localname(p_el.tag) == 'p':
                pid = p_el.get('id')
                if pid is None:
                    pid = str(id(p_el))
                after_para_texts[pid] = _collect_text_under(p_el)

        _remove_layout_cache_for_changed_paras(root_after, before_para_texts, after_para_texts)

        out_bytes = _serialize_xml(tree_after, decl_before or decl_after, encoding)
        path.write_bytes(out_bytes)

    return 0


if __name__ == '__main__':
    raise SystemExit(main())

